#!/usr/bin/env bash
set -euo pipefail

branch=chore/refresh-lockfile
proof_json=tests/runner-e2e/report-lock.json
proof_patch=tests/runner-e2e/report-lock.patch
registry_json=tests/runner-e2e/source-sdk-public-inputs.json
base_sha="$BASE_SHA"
repository="$REPOSITORY"
app_login="$APP_LOGIN"

[[ "$repository" == "groktopus/proprio" ]]
[[ "$base_sha" =~ ^[0-9a-f]{40}$ ]]
[[ "$app_login" =~ ^[a-z0-9][a-z0-9-]*\[bot\]$ ]]
test "$(git rev-parse HEAD)" = "$base_sha"

latest_main_sha="$(git ls-remote origin refs/heads/main | awk 'NR == 1 {print $1}')"
[[ "$latest_main_sha" == "$base_sha" ]] || { echo '::error::main advanced during proof generation.'; exit 1; }

# REST's `head=OWNER:BRANCH` query is exact and owner-qualified.
prs="$(gh api "repos/$repository/pulls?state=open&base=main&head=groktopus%3Achore%2Frefresh-lockfile&per_page=100")"
pr_count="$(jq 'length' <<< "$prs")"
(( pr_count <= 1 )) || { echo '::error::Multiple open PRs use the fixed reporting-lock branch.'; exit 1; }
pr_number=""
pr_head_sha=""
if (( pr_count == 1 )); then
  pr_author="$(jq -r '.[0].user.login' <<< "$prs")"
  pr_head_ref="$(jq -r '.[0].head.ref' <<< "$prs")"
  pr_base_ref="$(jq -r '.[0].base.ref' <<< "$prs")"
  pr_head_repo="$(jq -r '.[0].head.repo.full_name // empty' <<< "$prs")"
  pr_number="$(jq -r '.[0].number' <<< "$prs")"
  pr_head_sha="$(jq -r '.[0].head.sha' <<< "$prs")"
  [[ "$pr_author" == "$app_login" && "$pr_head_ref" == "$branch" && "$pr_base_ref" == "main" && "$pr_head_repo" == "$repository" ]]
fi

branch_sha="$(git ls-remote origin "refs/heads/$branch" | awk 'NR == 1 {print $1}')"
if [[ -n "$pr_number" ]]; then
  [[ -n "$branch_sha" && "$branch_sha" == "$pr_head_sha" ]] || { echo '::error::Open proof PR and fixed branch do not point to the same commit.'; exit 1; }
fi

verify_existing_commit() {
  local sha="$1" metadata author verified parent_count parent_sha
  metadata="$(gh api "repos/$repository/commits/$sha" --jq '[.author.login, .commit.verification.verified, (.parents | length), .parents[0].sha] | @tsv')"
  IFS=$'\t' read -r author verified parent_count parent_sha <<< "$metadata"
  [[ "$author" == "$app_login" && "$verified" == "true" && "$parent_count" == "1" && "$parent_sha" == "$base_sha" ]] || {
    echo '::error::Existing fixed branch is not one verified App commit directly based on this exact main revision.'
    return 1
  }
  git fetch --no-tags origin "refs/heads/$branch"
  [[ "$(git rev-parse FETCH_HEAD)" == "$sha" ]]
  local changed
  changed="$(git diff --name-only "$base_sha..$sha")"
  [[ -n "$changed" ]] || { echo '::error::Existing App commit has no changes.'; return 1; }
  while IFS= read -r file; do
    case "$file" in
      "$proof_json"|"$proof_patch"|"$registry_json") ;;
      *) echo '::error::Existing App commit changes paths outside the reporting proof and its SDK pin registry.'; return 1 ;;
    esac
  done <<< "$changed"
  for file in "$proof_json" "$proof_patch" "$registry_json"; do
    local wanted actual
    wanted="$(sha256sum "$file" | awk '{print $1}')"
    actual="$(git show "$sha:$file" | sha256sum | awk '{print $1}')"
    [[ "$actual" == "$wanted" ]] || {
      echo '::error::Existing verified App branch has generated bytes that differ from this run.'
      return 1
    }
  done
}

create_pr() {
  gh pr create --repo "$repository" --base main --head "$branch" \
    --title 'chore(runner): refresh reporting lock proof' \
    --body 'Refresh the Runner reporting-lock proof from a trusted main lock. This PR is not auto-merged; normal protected checks remain required.'
}

if [[ -n "$branch_sha" && "$branch_sha" != "$base_sha" ]]; then
  verify_existing_commit "$branch_sha"
  if [[ -z "$pr_number" ]]; then
    create_pr
  fi
  exit 0
fi

if [[ -n "$pr_number" ]]; then
  echo '::error::Open proof PR has no generated proof commit.'
  exit 1
fi

if [[ -z "$branch_sha" ]]; then
  gh api --method POST "repos/$repository/git/refs" -f "ref=refs/heads/$branch" -f "sha=$base_sha" >/dev/null
fi

latest_main_sha="$(git ls-remote origin refs/heads/main | awk 'NR == 1 {print $1}')"
[[ "$latest_main_sha" == "$base_sha" ]] || { echo '::error::main advanced before proof commit creation.'; exit 1; }

query='mutation($input: CreateCommitOnBranchInput!) { createCommitOnBranch(input: $input) { commit { oid signature { isValid wasSignedByGitHub } } } }'
input_file="$RUNNER_TEMP/create-report-proof-commit.json"
jq -n \
  --arg query "$query" \
  --arg repository "$repository" \
  --arg branch "$branch" \
  --arg base "$base_sha" \
  --rawfile policy "$proof_json" \
  --rawfile patch "$proof_patch" \
  --rawfile registry "$registry_json" \
  '{query:$query,variables:{input:{branch:{repositoryNameWithOwner:$repository,branchName:$branch},expectedHeadOid:$base,message:{headline:"chore(runner): refresh reporting lock proof",body:"Generated from a trusted main lock."},fileChanges:{additions:[{path:"tests/runner-e2e/report-lock.json",contents:($policy|@base64)},{path:"tests/runner-e2e/report-lock.patch",contents:($patch|@base64)},{path:"tests/runner-e2e/source-sdk-public-inputs.json",contents:($registry|@base64)}],deletions:[]}}}}' > "$input_file"
result="$(gh api graphql --input "$input_file")"
commit_sha="$(jq -r '.data.createCommitOnBranch.commit.oid // empty' <<< "$result")"
signature_valid="$(jq -r '.data.createCommitOnBranch.commit.signature.isValid // false' <<< "$result")"
github_signed="$(jq -r '.data.createCommitOnBranch.commit.signature.wasSignedByGitHub // false' <<< "$result")"
[[ "$commit_sha" =~ ^[0-9a-f]{40}$ && "$signature_valid" == true && "$github_signed" == true ]] || {
  echo '::error::GitHub did not return a valid GitHub-signed proof commit.'
  exit 1
}

metadata="$(gh api "repos/$repository/commits/$commit_sha" --jq '[.author.login, .commit.verification.verified, (.parents | length), .parents[0].sha] | @tsv')"
IFS=$'\t' read -r author verified parent_count parent_sha <<< "$metadata"
[[ "$author" == "$app_login" && "$verified" == true && "$parent_count" == 1 && "$parent_sha" == "$base_sha" ]] || {
  echo '::error::Signed commit author, signature verification, or exact base parent did not match the configured App policy.'
  exit 1
}

latest_main_sha="$(git ls-remote origin refs/heads/main | awk 'NR == 1 {print $1}')"
[[ "$latest_main_sha" == "$base_sha" ]] || { echo '::error::main advanced before the proof PR could be opened.'; exit 1; }
create_pr
